UTC = timezone.utc
EPOCH = datetime(1970, 1, 1, tzinfo=UTC)


def read_text(path):
    b = Path(path).read_bytes()
    if b[:2] == b"\x1f\x8b":
        b = gzip.decompress(b)
    return b.decode("utf-8-sig")


def lines_of(text):
    return [l for l in text.splitlines() if l.strip() != ""]


def to_epoch(dt):
    return int((dt - EPOCH).total_seconds())


def local_to_epoch(tz, naive, fold=0):
    return to_epoch(naive.replace(tzinfo=tz, fold=fold))


def std_offset(tz):
    for m in range(1, 13):
        d = datetime(2026, m, 1, tzinfo=tz)
        if not d.dst():
            return d.utcoffset()
    return datetime(2026, 1, 1, tzinfo=tz).utcoffset()


def pid(x):
    s = str(x).strip()
    return str(int(s)) if isinstance(x, int) else s


def parse_abbr(text, tz):
    out = []
    header = None
    for row in csv.reader(io.StringIO("\n".join(lines_of(text)))):
        row = [c.strip() for c in row]
        if "Badge" in row and "Punch" in row:
            header = row
            continue
        if header is None:
            continue
        r = dict(zip(header, row))
        d = datetime.strptime(r["Date"], "%m/%d/%Y")
        t = r["Time"].upper()
        if t.endswith("AM") or t.endswith("PM"):
            tm = datetime.strptime(t, "%I:%M:%S %p")
        else:
            tm = datetime.strptime(t, "%H:%M:%S")
        naive = d.replace(hour=tm.hour, minute=tm.minute, second=tm.second)
        fold = 1 if r["Zone"].upper().endswith("ST") else 0
        out.append((r["Record"], r["Badge"], r["Punch"].upper(), local_to_epoch(tz, naive, fold)))
    return out


def parse_epoch(text):
    out = []
    schema = 1
    for l in lines_of(text):
        o = json.loads(l)
        if "schema" in o and "id" not in o and "punch_id" not in o:
            schema = int(o["schema"])
            continue
        if o.get("heartbeat"):
            continue
        if schema == 2:
            out.append((pid(o["punch_id"]), o["employee"], o["direction"].upper(), int(o["epoch_ms"]) // 1000))
        else:
            ts = int(o["ts"]) if "ts" in o else int(o["ts_ms"]) // 1000
            out.append((pid(o["id"]), o["emp"], o["dir"].upper(), ts))
    return out


def parse_offset(text):
    out = []
    for r in csv.DictReader(io.StringIO("\n".join(lines_of(text))), delimiter=";"):
        dt = datetime.fromisoformat(r["timestamp"])
        d = "IN" if r["event"] == "clock_in" else "OUT"
        out.append((r["punch_id"].strip(), r["employee"].strip(), d, to_epoch(dt)))
    return out


def parse_legacy(text, tz):
    out = []
    off = std_offset(tz)
    for l in lines_of(text):
        t = l[0]
        if t == "H":
            o = l[13:18].strip()
            if o:
                sign = -1 if o[0] == "-" else 1
                off = sign * timedelta(hours=int(o[1:3]), minutes=int(o[3:5]))
            else:
                off = std_offset(tz)
        elif t == "D":
            naive = datetime.strptime(l[16:30], "%Y%m%d%H%M%S")
            ep = to_epoch(naive.replace(tzinfo=UTC)) - int(off.total_seconds())
            out.append((l[1:9], "E" + l[9:15].strip(), "IN" if l[15] == "I" else "OUT", ep))
    return out


def parse_de(text, tz):
    out = []
    for r in csv.DictReader(io.StringIO("\n".join(lines_of(text))), delimiter="\t"):
        r = {k.strip(): v.strip() for k, v in r.items()}
        naive = datetime.strptime(r["Datum"] + " " + r["Uhrzeit"], "%d.%m.%Y %H:%M")
        fold = 1 if r["Zeitzone"].upper() == "MEZ" else 0
        out.append((r["Nr"], r["Ausweis"], "IN" if r["Buchung"] == "K" else "OUT", local_to_epoch(tz, naive, fold)))
    return out


def parse_local_csv(text, tz):
    out = []
    for r in csv.DictReader(io.StringIO("\n".join(lines_of(text)))):
        naive = datetime.strptime(r["local_time"].strip(), "%Y-%m-%d %H:%M:%S")
        out.append((r["punch_ref"].strip(), r["employee_id"].strip(), r["direction"].strip().upper(),
                    local_to_epoch(tz, naive, 0)))
    return out


def parse_local_jsonl(text, tz):
    out = []
    for l in lines_of(text):
        p = json.loads(l)["punch"]
        naive = datetime.strptime(p["at"], "%Y-%m-%d %H:%M:%S")
        out.append((pid(p["id"]), p["badge"], p["type"].upper(), local_to_epoch(tz, naive, 0)))
    return out


