        d = indir / "exports" / site
        if not d.is_dir():
            continue
        for p in sorted(x for x in d.rglob("*") if x.is_file()):
            text = read_text(p)
            if fmt == "abbr-csv": rows = parse_abbr(text, tz)
            elif fmt == "epoch-jsonl": rows = parse_epoch(text)
            elif fmt == "offset-csv": rows = parse_offset(text)
            elif fmt == "legacy-fixed": rows = parse_legacy(text, tz)
            elif fmt == "de-tsv": rows = parse_de(text, tz)
            elif fmt == "local-csv": rows = parse_local_csv(text, tz)
            elif fmt == "local-jsonl": rows = parse_local_jsonl(text, tz)
            else: raise SystemExit("unknown format " + fmt)
            for i, e, dr, ep in rows:
                k = (site, i)
                ever.add(k)
                if k not in punches:
                    punches[k] = [e.strip(), dr, ep]

    # 2. corrections
    corr = []
    cdir = indir / "corrections"
    if cdir.is_dir():
        for p in sorted(x for x in cdir.rglob("*") if x.is_file()):
            for r in csv.DictReader(io.StringIO("\n".join(lines_of(read_text(p))))):
                r = {k.strip(): (v or "").strip() for k, v in r.items() if k}
                r["_at"] = datetime.fromisoformat(r["issued_at"].replace("Z", "+00:00"))
                corr.append(r)
    corr.sort(key=lambda r: (r["_at"], r["correction_id"]))
    applied = 0
    voided = set()
    for r in corr:
        if r["_at"] > cutoff:
            continue
        k = (r["site"], r["punch_id"])
        a = r["action"]
        if a == "void":
            if k in punches and k not in voided:
                del punches[k]; voided.add(k); applied += 1
        elif a == "set":
            if k in punches:
                punches[k][2] = to_epoch(datetime.fromisoformat(r["time"])); applied += 1
        elif a == "add":
            if k not in ever and r["site"] in sites:
                ever.add(k)
                punches[k] = [r["employee"], r["type"].upper(), to_epoch(datetime.fromisoformat(r["time"]))]
                applied += 1

    byemp = {}
    for (site, i), (e, dr, ep) in punches.items():
        if e in employees:
            byemp.setdefault(e, []).append((ep, 0 if dr == "OUT" else 1, site, i, dr))

