        off = int(datetime.fromtimestamp(ep, UTC).astimezone(tz).utcoffset().total_seconds())
        le = ep + off
        return ((le + 180) // 360) * 360 - off

    def workday(ep, home):
        return datetime.fromtimestamp(ep, UTC).astimezone(home).date()

    exc = {"open_shifts": 0, "orphan_outs": 0, "duplicates_dropped": 0, "corrections_applied": applied}
    res = {}
    for e, home_site in employees.items():
        home = sites[home_site][0]
        ps = sorted(byemp.get(e, []))
        kept = []
        last = None
        for ep, _, site, i, dr in ps:
            tz = sites[site][0]
            r = rnd(ep, tz)
            if last is not None and last[4] == dr and ep - last[0] <= 300:
                if pstart <= workday(r, home) <= pend:
                    exc["duplicates_dropped"] += 1
                continue
            t = (ep, 0, site, i, dr, r)
            kept.append(t)
            last = t
        shifts = []
        cur = None

        def openshift(c):
            if pstart <= workday(c[5], home) <= pend:
                exc["open_shifts"] += 1

        for t in kept:
            if t[4] == "IN":
                if cur: openshift(cur)
                cur = t
            else:
                if cur and t[5] - cur[5] <= 16 * 3600:
                    shifts.append((cur, t)); cur = None
                else:
                    if cur: openshift(cur); cur = None
                    if pstart <= workday(t[5], home) <= pend:
                        exc["orphan_outs"] += 1
        if cur: openshift(cur)

        rows = []
        for i_, o_ in shifts:
            wd = workday(i_[5], home)
            if not (pstart <= wd <= pend):
                continue
            worked = max(0, (o_[5] - i_[5]) // 60)
            paid = worked - 30 if worked > 360 else worked
