            night = 0
            for s in range(i_[5], o_[5], 360):
                h = datetime.fromtimestamp(s, UTC).astimezone(tz).hour
                if h >= 22 or h < 6:
                    night += 6
            night = min(night, paid)
            rows.append([i_[5], wd, paid, night, 0])
        rows.sort(key=lambda x: x[0])
        # daily OT
        daily = {}
        for r in rows:
            u = daily.get(r[1], 0)
            ot = max(0, u + r[2] - 480) - max(0, u - 480)
            daily[r[1]] = u + r[2]
            r.append(ot)  # r[5] daily ot
        weekly = {}
        for r in rows:
            wk = r[1] - timedelta(days=r[1].weekday())
            reg = r[2] - r[5]
            u = weekly.get(wk, 0)
            wot = max(0, u + reg - 2400) - max(0, u - 2400)
            weekly[wk] = u + reg
            r[4] = r[5] + wot
        pay = Decimal(0)
        for r in rows:
            rate = None
            for ef, v in rates.get(e, []):
                if ef <= r[1]:
                    rate = v
            if rate is None:
                rate = Decimal(0)
            reg = r[2] - r[4]
            pay += rate * (Decimal(reg) + Decimal("1.5") * r[4]) / 60 + rate * Decimal("0.15") * r[3] / 60
        gross = pay.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        res[e] = {"shifts": len(rows), "paid_minutes": sum(r[2] for r in rows),
                  "overtime_minutes": sum(r[4] for r in rows), "night_minutes": sum(r[3] for r in rows),
                  "gross": gross}

    tot = {"shifts": 0, "paid_minutes": 0, "overtime_minutes": 0, "night_minutes": 0, "gross": Decimal(0)}
    for v in res.values():
        for k in tot:
            tot[k] += v[k]
    fmt = lambda v: {**v, "gross": f"{v['gross']:.2f}"}
    out = {"period": {"start": period["start"], "end": period["end"]},
           "employees": {e: fmt(v) for e, v in res.items()},
           "exceptions": exc, "totals": fmt(tot)}
    Path(outfile).write_text(json.dumps(out, indent=1))


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
